#!/usr/bin/env bash
# Regenerates this directory's config.h - the header generated by hunspell's
# autotools and checked into the parent repo, used to define things when
# hunspell is built inside the Pareizrakstiba binary.
#
# How it works: if the submodule checkout has no ./configure script yet, it
# is generated with autoreconf; then ./configure runs inside the submodule
# and the resulting config.h is copied here.
#
# autoreconf and ./configure run with a restricted PATH so
# that machine-specific tool installs (e.g., Homebrew in /opt/homebrew/bin)
# cannot influence the checks on a standard macOS setup (see STANDARD_PATH)
#
#   /usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin:/pkg/env/global/bin
#
# On a machine that keeps its tools elsewhere, override the PATH for one
# run without changing the default:
#
#   HUNSPELL_CONFIGURE_PATH="/usr/bin:/bin" ./generate-config.sh
#
# The script never stages anything; review and stage config.h yourself:
#
#   git diff -- vendors/hunspell/config.h
#   git add vendors/hunspell/config.h
#
# Usage: ./generate-config.sh
#
# Requires autotools on the (possibly overridden) PATH: autoconf, automake,
# GNU libtool (whose libtool.m4 must be visible to aclocal) and gettext.

set -euo pipefail

STANDARD_PATH=/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin:/pkg/env/global/bin

SCRIPT_DIR=$( cd "$( dirname "${BASH_SOURCE[0]}" )" && pwd )
SUPER=$( git -C "${SCRIPT_DIR}" rev-parse --show-toplevel )

SUBREL=$( git -C "${SUPER}" config --file "${SUPER}/.gitmodules" --get-regexp '\.path$' \
	| awk '{print $2}' | head -n 1 )
if [ -z "${SUBREL}" ]; then
	echo "error: no submodule entry found in .gitmodules" >&2
	exit 1
fi
SUB="${SUPER}/${SUBREL}"
CONFIG_H="${SCRIPT_DIR}/config.h"

if [ ! -e "${SUB}/.git" ]; then
	echo "error: submodule not initialized; run:" >&2
	echo "  git submodule update --init ${SUBREL}" >&2
	exit 1
fi

export PATH="${HUNSPELL_CONFIGURE_PATH:-${STANDARD_PATH}}"

# Pre-flight: every tool autoreconf needs must exist, and aclocal must be able
# to see GNU libtool's libtool.m4 - hunspell's configure.ac uses LT_INIT, and
# Apple's /usr/bin/libtool is a different tool that ships no m4 macros.

MISSING=""
for TOOL in autoreconf aclocal autopoint; do
	command -v "${TOOL}" >/dev/null 2>&1 || MISSING="${MISSING} ${TOOL}"
done
if ! command -v libtoolize >/dev/null 2>&1 \
	&& ! command -v glibtoolize >/dev/null 2>&1; then
	MISSING="${MISSING} libtoolize"
fi
if [ -n "${MISSING}" ]; then
	echo "error: autotools missing from PATH: ${PATH}" >&2
	echo "missing:${MISSING}" >&2
	echo "The standard macOS PATH is used by default so machine-specific tools" >&2
	echo "cannot change the result. Install the autotools (autoconf, automake," >&2
	echo "libtool, gettext) so they are on that PATH, or point" >&2
	echo "HUNSPELL_CONFIGURE_PATH at a directory that has them, for example:" >&2
	echo "  HUNSPELL_CONFIGURE_PATH=\"/opt/homebrew/bin:/usr/bin:/bin\" $( basename "${BASH_SOURCE[0]}" )" >&2
	exit 1
fi

# Homebrew's libtool names the binary glibtoolize; autoreconf looks for
# libtoolize, so point it at the prefixed name.
if ! command -v libtoolize >/dev/null 2>&1 \
	&& command -v glibtoolize >/dev/null 2>&1; then
	export LIBTOOLIZE=glibtoolize
fi

# If libtool.m4 is not in aclocal's default directory but a Homebrew libtool
# provides it in its (possibly keg-only) prefix, extend ACLOCAL_PATH for this
# run rather than failing.
ACLOCAL_DIR=$( aclocal --print-ac-dir 2>/dev/null || true )
if [ -n "$( command -v brew || true )" ] \
	&& [ ! -f "${ACLOCAL_DIR}/libtool.m4" ] \
	&& [ -f "$( brew --prefix )/opt/libtool/share/aclocal/libtool.m4" ]; then
	BREW_LIBTOOL_ACLOCAL="$( brew --prefix )/opt/libtool/share/aclocal"
	export ACLOCAL_PATH="${ACLOCAL_PATH:+${ACLOCAL_PATH}:}${BREW_LIBTOOL_ACLOCAL}"
fi
LIBTOOL_M4_FOUND=""
for DIR in "${ACLOCAL_DIR}" $( echo "${ACLOCAL_PATH:-}" | tr ':' ' ' ); do
	if [ -f "${DIR}/libtool.m4" ]; then
		LIBTOOL_M4_FOUND=yes
		break
	fi
done
if [ -z "${LIBTOOL_M4_FOUND}" ]; then
	echo "error: aclocal cannot find libtool.m4 (hunspell's configure.ac uses" >&2
	echo "LT_INIT, and Apple's /usr/bin/libtool does not ship autotools macros)." >&2
	echo "Install GNU libtool so its m4 macros are on aclocal's search path, e.g.:" >&2
	echo "  brew install libtool" >&2
	exit 1
fi

cd "${SUB}"

echo "Generating config.h from hunspell $( git describe --tags 2>/dev/null || echo 'unknown version' )"

if [ ! -f configure ]; then
	autoreconf -i
fi
./configure

if [ ! -f config.h ]; then
	echo "error: configure did not produce config.h" >&2
	exit 1
fi

cp config.h "${CONFIG_H}"

# Remove the autotools output from the submodule so it stays a pristine
# checkout; the generated config.h was already copied out.
git clean -fdxq

echo
echo "Generated ${CONFIG_H}"
echo "Review it with:  git diff -- ${CONFIG_H}"
echo "Stage it with:   git add ${CONFIG_H}"
